const fs = require('fs');
const path = require('path');

// Accepted grammar: blank lines and lines whose first non-space character is
// `#` are ignored; `key=value` yields a string value, splitting on the first
// `=` so values may contain more; a bare `key` is a flag and yields `true`.
// A later assignment to the same key wins.
function parseConfig(text) {
  // Null-prototype: config text is untrusted input, and a key named
  // `__proto__` or `constructor` must not be able to reach Object.prototype.
  const config = Object.create(null);
  for (const line of text.split('\n')) {
    const trimmed = line.trim();
    if (trimmed === '' || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    if (eq === -1) {
      config[trimmed] = true;
      continue;
    }
    config[trimmed.slice(0, eq).trim()] = trimmed.slice(eq + 1).trim();
  }
  return config;
}

function loadConfig(filePath) {
  // Read once at startup, before anything is serving: the synchronous call
  // costs nothing that matters here and keeps every caller free of a promise.
  let text;
  try {
    text = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    // A missing config is the likeliest startup failure, and the raw ENOENT
    // does not say which path was actually tried.
    if (err.code === 'ENOENT') {
      throw new Error(`Config file not found: ${path.resolve(filePath)}`);
    }
    throw err;
  }
  return parseConfig(text);
}

