const test = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const os = require('os');
const path = require('path');

const { parseConfig, loadConfig } = require('../src/config');

test('parses key=value pairs', () => {
  assert.strictEqual(parseConfig('name=world').name, 'world');
});

test('treats a bare key as a flag', () => {
  assert.strictEqual(parseConfig('DEBUG').DEBUG, true);
});

test('splits on the first = so values may contain more', () => {
  assert.strictEqual(parseConfig('a=b=c').a, 'b=c');
});

test('ignores blank lines and comments', () => {
  const config = parseConfig('# comment\n\n  \nname=world\n');
  assert.deepStrictEqual(Object.keys(config), ['name']);
});

test('trims surrounding whitespace and CRLF line endings', () => {
  const config = parseConfig('a = 1 \r\nb=2\r\n');
  assert.strictEqual(config.a, '1');
  assert.strictEqual(config.b, '2');
});

test('last assignment to a key wins', () => {
  assert.strictEqual(parseConfig('a=1\na=2').a, '2');
});

test('a __proto__ key does not reach Object.prototype', () => {
  const config = parseConfig('__proto__=polluted');
  assert.strictEqual(config.__proto__, 'polluted');
  assert.strictEqual({}.polluted, undefined);
  assert.strictEqual(Object.prototype.__proto__, Object.getPrototypeOf(Object.prototype));
});

test('parses the shipped app.conf', () => {
  const config = loadConfig(path.join(__dirname, '..', 'app.conf'));
  assert.strictEqual(config.name, 'world');
  assert.strictEqual(config.DEBUG, true);
});

test('reports the resolved path when the config file is missing', () => {
  const missing = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'config-')), 'absent.conf');
  assert.throws(() => loadConfig(missing), (err) => err.message === `Config file not found: ${missing}`);
});

